import React, { useEffect, useState } from 'react';

function LifetimeWithdraw() {
  const [lifetimeWinning, setLifetimeWinning] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  useEffect(() => {
    fetch('/api/withdraw/lifetime', {
      method: 'GET',
      headers: {
        'Content-Type': 'application/json',
        // যদি টোকেন লাগে, এখানে অ্যাড করো:
        // 'Authorization': `Bearer ${yourToken}`,
      },
    })
      .then(async (res) => {
        if (!res.ok) {
          const errorText = await res.text();
          throw new Error(errorText || 'Failed to fetch lifetime winning');
        }
        return res.json();
      })
      .then(data => {
        // যেহেতু ব্যাকএন্ড থেকে { total: <number> } আসছে
        setLifetimeWinning(data.total);
        setLoading(false);
      })
      .catch(err => {
        setError(err.message);
        setLoading(false);
      });
  }, []);

  if (loading) return <div>লোড হচ্ছে...</div>;
  if (error) return <div>ত্রুটি: {error}</div>;

  return (
    <div>
      <h2>লাইফটাইম উইনিং</h2>
      <p>৳ {lifetimeWinning}</p>
    </div>
  );
}

export default LifetimeWithdraw;
